UPDATE businesses SET description = 'Deer Park Cafe is a neighbourhood restaurant in Vredehoek that opens onto a public park overlooking the city, shaded by stone-pine and yellowwood trees. The weekly changing menu always features authentic Indian dishes, prepared under a chef from Goa, alongside vegan and vegetarian options, fresh pasta, hand-rolled wood-fired pizzas and a popular children''s menu.

Ingredients are free-range, fresh, local and seasonal, and the drinks list covers good coffee, wines, craft beers and cocktails. The cafe opens daily from 8am to 9pm in winter and until 10pm in summer, and on busy summer days when all tables are taken, visitors are encouraged to order pizzas to enjoy on a picnic blanket in the park. It suits families and regulars wanting a relaxed, park-side meal with a reliably interesting menu.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://deerparkcafe.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'deer-park-cafe-vredehoek' AND description = 'Deer Park Cafe is a restaurant in Vredehoek known for a weekly changing menu that always features authentic Indian specials, alongside vegan, gluten-free and free-range options.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
